// ─────────── среда выполнения bit (x86_64) ───────────
// аргументы: rdi, rsi, rdx, rcx, r8, r9; результат: rax
.p2align 4
_bit_recover_enter:                 // → rax = буфер перехода; глубину +1
    mov rax, [rip + Lrt_recdepth]
    mov rcx, rax
    shl rcx, 9
    lea rdx, [rip + Lrt_recbufs]
    add rdx, rcx
    inc rax
    mov [rip + Lrt_recdepth], rax
    mov rax, rdx
    ret

_bit_recover_leave:                 // глубину -1 (обычный выход из recover)
    mov rax, [rip + Lrt_recdepth]
    dec rax
    mov [rip + Lrt_recdepth], rax
    ret

_bit_setjmp:                        // rdi = буфер → 0; сохраняет callee-saved, sp и адрес возврата
    mov [rdi], rbx
    mov [rdi + 8], rbp
    mov [rdi + 16], r12
    mov [rdi + 24], r13
    mov [rdi + 32], r14
    mov [rdi + 40], r15
    lea rdx, [rsp + 8]
    mov [rdi + 48], rdx
    mov rdx, [rsp]
    mov [rdi + 56], rdx
    xor eax, eax
    ret

_bit_longjmp:                       // rdi = буфер, rsi = значение → возврат из _bit_setjmp
    mov rbx, [rdi]
    mov rbp, [rdi + 8]
    mov r12, [rdi + 16]
    mov r13, [rdi + 24]
    mov r14, [rdi + 32]
    mov r15, [rdi + 40]
    mov rsp, [rdi + 48]
    mov rax, rsi
    jmp qword ptr [rdi + 56]

_bit_term_error:                    // → копия текста последней пойманной ошибки ("" если не было)
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    mov rbx, [rip + Lrt_errmsg]
    test rbx, rbx
    jnz 1f
    mov edi, 1
    call _bit_alloc
    mov byte ptr [rax], 0
    jmp 2f
1:  mov rdi, rbx
    call strlen@PLT
    mov rsi, rax
    mov rdi, rbx
    call _bit_substr
2:  pop r12
    pop rbx
    pop rbp
    ret

_bit_die:                           // rdi = сообщение, rsi = строка программы
    mov rax, [rip + Lrt_recdepth]
    test rax, rax
    jz 5f
    mov [rip + Lrt_errmsg], rdi
    mov [rip + Lrt_errline], rsi
    dec rax
    mov [rip + Lrt_recdepth], rax
    mov rcx, rax
    shl rcx, 9
    lea rdi, [rip + Lrt_recbufs]
    add rdi, rcx
    mov esi, 1
    jmp _bit_longjmp
5:  push rbp
    mov rbp, rsp
    push rbx
    push r12
    mov rbx, rdi
    mov r12, rsi
    xor edi, edi
    call fflush@PLT
    mov rax, [rip + stderr@GOTPCREL]
    mov rdi, [rax]
    lea rsi, [rip + Lrt_die]
    mov rdx, r12
    mov rcx, rbx
    xor eax, eax
    call fprintf@PLT
    mov edi, 1
    call exit@PLT

_bit_oom:
    and rsp, -16
    lea rdi, [rip + Lrt_oom]
    xor esi, esi
    call _bit_die

_bit_alloc:                         // rdi = байты → rax = память
    push rbp
    mov rbp, rsp
    call malloc@PLT
    test rax, rax
    jz _bit_oom
    pop rbp
    ret

_bit_print:                         // rdi = строка
    push rbp
    mov rbp, rsp
    call puts@PLT
    pop rbp
    ret

_bit_num_str:                       // rdi = num → строка
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    mov rbx, rdi
    mov edi, 32
    call _bit_alloc
    mov r12, rax
    mov rdi, rax
    mov esi, 32
    lea rdx, [rip + Lrt_lld]
    mov rcx, rbx
    xor eax, eax
    call snprintf@PLT
    mov rax, r12
    pop r12
    pop rbx
    pop rbp
    ret

_bit_dec_str:                       // rdi = биты dec → самая короткая точная запись
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov edi, 48
    call _bit_alloc
    mov r12, rax
    mov r13d, 15
1:  mov rdi, r12
    mov esi, 44
    lea rdx, [rip + Lrt_gp]
    mov ecx, r13d
    movq xmm0, rbx
    mov eax, 1
    call snprintf@PLT
    cmp r13d, 17
    jge 2f
    mov rdi, r12
    xor esi, esi
    call strtod@PLT
    movq rax, xmm0
    cmp rax, rbx
    je 2f
    inc r13d
    jmp 1b
2:  mov rdi, r12
    lea rsi, [rip + Lrt_decch]
    call strpbrk@PLT
    test rax, rax
    jnz 3f
    mov rdi, r12
    lea rsi, [rip + Lrt_dot0]
    call strcat@PLT
3:  mov rax, r12
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_bool_str:                      // rdi = bool → строка
    lea rax, [rip + Lrt_true]
    test rdi, rdi
    jnz 1f
    lea rax, [rip + Lrt_false]
1:  ret

_bit_string_str:
    mov rax, rdi
    ret

_bit_to_str:                        // rdi = значение, rsi = вид (0 num, 1 dec, 2 string, 3 bool)
    cmp rsi, 0
    je _bit_num_str
    cmp rsi, 1
    je _bit_dec_str
    cmp rsi, 3
    je _bit_bool_str
    mov rax, rdi
    ret

_bit_cat:                           // rdi = a, rsi = b → новая строка a+b
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8
    mov rbx, rdi
    mov r12, rsi
    call strlen@PLT
    mov r13, rax
    mov rdi, r12
    call strlen@PLT
    mov r14, rax
    lea rdi, [r13 + r14 + 1]
    call _bit_alloc
    mov r15, rax
    mov rdi, r15
    mov rsi, rbx
    mov rdx, r13
    call memcpy@PLT
    lea rdi, [r15 + r13]
    mov rsi, r12
    lea rdx, [r14 + 1]
    call memcpy@PLT
    mov rax, r15
    add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_str_eq:                        // rdi, rsi = строки → 1 если равны
    push rbp
    mov rbp, rsp
    call strcmp@PLT
    test eax, eax
    sete al
    movzx eax, al
    pop rbp
    ret

_bit_str_starts:                    // rdi=строка, rsi=начало → 1/0
1:  movzx eax, byte ptr [rsi]
    test al, al
    jz 2f
    movzx ecx, byte ptr [rdi]
    cmp al, cl
    jne 3f
    inc rdi
    inc rsi
    jmp 1b
2:  mov eax, 1
    ret
3:  xor eax, eax
    ret

_bit_str_ends:                      // rdi=строка, rsi=конец → 1/0
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov r12, rsi
    mov rdi, rsi
    call strlen@PLT
    mov r13, rax
    mov rdi, rbx
    call strlen@PLT
    cmp r13, rax
    jg 3f
    lea rdi, [rbx + rax]
    sub rdi, r13
    mov rsi, r12
    mov rcx, r13
1:  test rcx, rcx
    jz 2f
    movzx edx, byte ptr [rdi]
    movzx r8d, byte ptr [rsi]
    cmp dl, r8b
    jne 3f
    inc rdi
    inc rsi
    dec rcx
    jmp 1b
2:  mov eax, 1
    jmp 4f
3:  xor eax, eax
4:  pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_str_trim:                      // rdi=строка → новая строка без краёв-пробелов
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov r12, rdi
1:  movzx eax, byte ptr [r12]
    cmp al, 0x20
    je 2f
    cmp al, 0x09
    je 2f
    cmp al, 0x0A
    je 2f
    cmp al, 0x0D
    je 2f
    jmp 3f
2:  inc r12
    jmp 1b
3:  mov rdi, r12
    call strlen@PLT
    mov r13, rax
4:  test r13, r13
    jz 6f
    movzx eax, byte ptr [r12 + r13 - 1]
    cmp al, 0x20
    je 5f
    cmp al, 0x09
    je 5f
    cmp al, 0x0A
    je 5f
    cmp al, 0x0D
    je 5f
