    mov r14, rcx
    mov edi, 8
    call _bit_bytes_new
    mov rcx, [rax]
    mov [rcx], r13
    mov rdi, rbx
    mov rsi, r12
    mov rdx, rax
    mov rcx, r14
    call _bit_proc_write
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_proc_try:                      // rdi=pid, rsi=адрес, rdx=сколько -> bytes или 0 (без ошибки)
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov r12, rsi
    mov r13, rdx
    lea rsi, [rip + Lrt_fmem]
    call _bit_proc_path
    mov rbx, rax
    mov rdi, r13
    call _bit_bytes_new
    mov r14, rax
    mov rdi, rbx
    xor esi, esi
    xor eax, eax
    call open@PLT
    test eax, eax
    js 8f
    mov ebx, eax
    mov edi, ebx
    mov rsi, [r14]
    mov rdx, r13
    mov rcx, r12
    call pread@PLT
    cmp rax, r13
    jne 7f
    mov edi, ebx
    call close@PLT
    mov rax, r14
    jmp 9f
7:  mov edi, ebx
    call close@PLT
8:  xor eax, eax
9:  pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_proc_scan:                     // rdi=pid, rsi=число, rdx=строка -> mas:num адресов
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 72
    mov rbx, rdi
    mov r12, rsi
    mov r13, rdx
    mov rdi, rbx
    mov rsi, r13
    call _bit_proc_maps
    mov r15, rax
    mov rdi, -1
    xor esi, esi
    call _bit_mas_new
    mov r14, rax
    mov qword ptr [rbp - 48], 0
.Ls_loop:
    mov rax, [rbp - 48]
    cmp rax, [r15 + 8]
    jge .Ls_done
    mov rcx, [r15]
    mov rdi, [rcx + rax*8]
    call _bit_hexval_ptr
    mov [rbp - 56], rax
    cmp byte ptr [rdx], 45
    jne .Ls_next
    lea rdi, [rdx + 1]
    call _bit_hexval_ptr
    mov [rbp - 64], rax
    mov rdi, rdx
.Ls_sp:
    movzx eax, byte ptr [rdi]
    test eax, eax
    je .Ls_next
    cmp eax, 32
    je .Ls_perm
    inc rdi
    jmp .Ls_sp
.Ls_perm:
    inc rdi
    cmp byte ptr [rdi], 114
    jne .Ls_next
    mov rax, [rbp - 64]
    sub rax, [rbp - 56]
    test rax, rax
    jle .Ls_next
    mov rcx, 0x10000000
    cmp rax, rcx
    ja .Ls_next
    mov [rbp - 72], rax
    mov rdi, rbx
    mov rsi, [rbp - 56]
    mov rdx, [rbp - 72]
    call _bit_proc_try
    test rax, rax
    jz .Ls_next
    mov [rbp - 104], rax
    mov rcx, [rax]
    mov [rbp - 80], rcx
    mov qword ptr [rbp - 88], 0
    mov rax, [rbp - 72]
    sub rax, 8
    mov [rbp - 96], rax
.Ls_scan:
    mov r10, [rbp - 88]
    cmp r10, [rbp - 96]
    jg .Ls_region
    mov r8, [rbp - 80]
    mov rax, [r8 + r10]
    cmp rax, r12
    jne .Ls_sn
    mov rsi, [rbp - 56]
    add rsi, r10
    mov rdi, r14
    mov rdx, r13
    call _bit_mas_add
.Ls_sn:
    mov r10, [rbp - 88]
    inc r10
    mov [rbp - 88], r10
    jmp .Ls_scan
.Ls_region:
    mov rdi, [rbp - 80]
    call free@PLT
    mov rdi, [rbp - 104]
    call free@PLT
.Ls_next:
    mov rax, [rbp - 48]
    inc rax
    mov [rbp - 48], rax
    jmp .Ls_loop
.Ls_done:
    mov rax, r14
    lea rsp, [rbp - 40]
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

